            ("तीन नयन रक्तिम अति शोभित । देखि रूप असुरन मन क्षोभित ॥ ४ ॥", "आपके तीनों नेत्र अग्नि के समान लाल और तेजस्वी हैं; इस उग्र रूप को देखकर असुरों के मन में भय का कम्प उत्पन्न हो जाता है।"),
            ("जिह्वा लपलप बाहर निकसी । खप्पर खड्ग करन में विकसी ॥ ५ ॥", "आपकी रक्तिम जिह्वा बाहर निकली हुई है, और आपके कर-कमलों में तीक्ष्ण खड्ग और रक्त से भरा खप्पर सुशोभित है।"),
            ("गले मुण्ड की माला राजै । बाजत नूपुर पैंजन बाजै ॥ ६ ॥", "आपके कण्ठ में पचास नरमुण्डों की पावन माला सुशोभित है, और चरणों में नूपुरों की दिव्य ध्वनि गूँज रही है।"),
            ("नर कंकालन आसन सोहै । रूप देखि शिवजी मन मोहै ॥ ७ ॥", "आप रणभूमि में दैत्यों के संहार के उपरांत विराजी हैं; आपकी इस अगाध शक्ति-छवि को देखकर देवाधिदेव शिव भी विस्मित हो जाते हैं।"),
            ("शिव के उर पर चरण धरि आई । लज्जित भई तुरत मुसकाई ॥ ८ ॥", "जब संहार के आवेश में आपका चरण भगवान् शिव के वक्षःस्थल पर पड़ा, तब अपनी भूल का भान होते ही आपने लज्जा से अपनी जिह्वा दबा ली।"),
            ("मधु कैटभ जब देवन घेरा । ब्रह्मा स्तुति कीन्ह घनेरा ॥ ९ ॥", "जब मधु और कैटभ नामक महादैत्यों ने देवताओं को सताया और वेदों का हरण किया, तब ब्रह्मा जी ने आपकी ही महाकाली रूप में स्तुति की।"),
            ("विष्णु नयन से तुम प्रगटाई । दैत्यन मारि सृष्टि बचाई ॥ १० ॥", "आप योगनिद्रा रूप से भगवान् विष्णु के नेत्रों से प्रकट हुईं और प्रभु के हाथों मधु-कैटभ का संहार कराकर सृष्टि की रक्षा की।"),
            ("महिषासुर अति गर्वित भारी । रक्तबीज सब जग संहारी ॥ ११ ॥", "जब महिषासुर और रक्तबीज जैसे महादैत्यों ने तीनों लोकों में भारी हाहाकार मचाया;"),
            ("चण्ड मुण्ड को पल में मारा । चामुण्डा नाम तिहूँ संसारा ॥ १२ ॥", "तब आपने चण्ड और मुण्ड का पल भर में संहार कर डाला, जिससे सम्पूर्ण संसार में आपका नाम 'चामुण्डा' प्रसिद्ध हुआ।"),
            ("रक्तबीज का रक्त पिया है । बूंद न पृथ्वी पर गिरन दिया है ॥ १३ ॥", "आपने रक्तबीज के शरीर से टपकने वाले रक्त की प्रत्येक बूंद को खप्पर में झेलकर पी लिया, जिससे उसके नए दैत्य उत्पन्न न हो सके।"),
            ("शुम्भ निशुम्भ को मारि गिराया । सुर मण्डल में हर्ष छाया ॥ १४ ॥", "आपने शुम्भ और निशुम्भ जैसे महादानवों का वध किया, जिससे सम्पूर्ण देवलोक में हर्ष और मंगलोत्सव छा गया।"),
            ("दश महाविद्या में प्रथम भवानी । आदि शक्ति काली कल्याणी ॥ १५ ॥", "दसों महाविद्याओं में प्रथम और सर्वप्रमुख महाविद्या आप ही हैं; हे आद्यशक्ति कल्याणी काली! आपको बारंबार नमन है।"),
            ("तारा छिन्नमस्ता तुम माता । बगुलामुखी भुवनेश्वरी त्राता ॥ १६ ॥", "तारा, छिन्नमस्ता, बगलामुखी और भुवनेश्वरी—ये सब आपके ही विविध अलौकिक शक्ति-स्वरूप हैं।"),
            ("त्रिपुर सुन्दरी भैरवी रूपा । मातंगी धूमावति अनूपा ॥ १७ ॥", "त्रिपुरसुन्दरी, त्रिपुरभैरवी, मातंगी और धूमावती—इन समस्त रूपों में आप ही जगत का कल्याण करती हैं।"),
            ("कमलासन पर बैठि सुहाई । लक्ष्मी रूप जगत सुखदाई ॥ १८ ॥", "कमल के आसन पर विराजकर आप ही माँ लक्ष्मी बनकर सम्पूर्ण संसार को धन-धान्य और सुख प्रदान करती हैं।"),
            ("कलकत्ता में दक्षिण काली । दर्शन करत होय निहाली ॥ १९ ॥", "कोलकाता के कालीघाट और दक्षिणेश्वर धाम में आप ही 'भवतारिणी दक्षिणा काली' के रूप में विराजमान हैं, जहाँ दर्शन मात्र से भक्त धन्य हो जाते हैं।"),
            ("उज्जयिनी में गढ़कालिका भवानी । कवि कालिदास कीन्ह कल्याणी ॥ २० ॥", "उज्जयिनी नगरी में आप ही 'गढ़कालिका' रूप में पूजित हैं, जिनकी कृपा से मूर्ख कालिदास महाकवि के रूप में विख्यात हुए।"),
            ("पावागढ़ में कालिका माई । भक्तन की सदा करति सहाई ॥ २१ ॥", "पावागढ़ पर्वत पर आप ही माँ कालिका के रूप में विराजती हैं और अपने अनन्य भक्तों की सदा रक्षा करती हैं।"),
            ("भूत पिशाच निकट नहिं आवैं । काली नाम जो निसिदिन गावैं ॥ २२ ॥", "जो मनुष्य रात-दिन माँ काली के पावन नाम का उच्चारण करता है, भूत-प्रेत और पिशाच उसके पास कभी नहीं फटक सकते।"),
            ("डाकिनी शाकिनी भय न सतावै । काली कृपा सदा सुख पावै ॥ २३ ॥", "डाकिनी, शाकिनी अथवा तांत्रिक बाधाएं उसे कभी नहीं सतातीं; माँ काली की कृपा से वह सदा निर्भय रहता है।"),
            ("अकाल मृत्यु से रक्षा कीजै । दीर्घायु का वर मोहिं दीजै ॥ २४ ॥", "हे महाकाली! मेरी अकाल मृत्यु और विषैले संकटों से रक्षा कीजिए और मुझे पूर्ण स्वस्थ व दीर्घायु जीवन प्रदान कीजिए।"),
            ("रोग शोक संताप विडारो । हे जगदम्बा हमहिं उबारो ॥ २५ ॥", "मेरे समस्त शारीरिक रोगों, मानसिक शोकों और संतापों का नाश कीजिए; हे जगदम्बा माँ! मेरा उद्धार कीजिए।"),
            ("शत्रु नाश कीजै महारानी । सुमिरौं इकचित तुम्हें भवानी ॥ २६ ॥", "मेरे समस्त आंतरिक व बाह्य शत्रुओं का शमन कीजिए; मैं एकाग्रचित्त होकर आपके ही पावन स्वरूप का स्मरण करता हूँ।"),
            ("काम क्रोध मद लोभ मिटाओ । हृदय कमल में आन समाओ ॥ २७ ॥", "मेरे अंतःकरण से काम, क्रोध, मद, लोभ आदि विकारों को मिटाकर मेरे हृदय-कमल में आकर निवास कीजिए।"),
            ("दीन अनाथ जानि मोहे माता । कृपा करहु हे त्रिभुवन त्राता ॥ २८ ॥", "मुझे दीन और अनाथ जानकर हे माता! मुझ पर कृपा कीजिए; आप ही तीनों लोकों की परम रक्षक हैं।"),
            ("तुम्हरे बिना नहिं कोई हमारा । तुम ही हो सब जग अधारा ॥ २९ ॥", "हे माँ काली! आपके बिना हमारा कोई रक्षक नहीं है; आप ही इस सम्पूर्ण चराचर जगत् की परम आधारशिला हैं।"),
            ("शरणागत की लाज निभाओ । भव सागर से पार लगाओ ॥ ३० ॥", "अपनी शरण में आए हुए इस सेवक की लाज रखिए और मुझे इस जन्म-मरण के भवसागर से पार उतार दीजिए।"),
            ("नित्त नेम करि पाठ सुनावे । सो नर सब सुख भोग लगावे ॥ ३१ ॥", "जो नियमपूर्वक नित्य यह महाकाली चालीसा पढ़ता या सुनता है, वह संसार के सम्पूर्ण सुखों का उपभोग करता है।"),
            ("पुत्र हीन को पुत्र सुहावन । निर्धन को धन देत पावन ॥ ३२ ॥", "आप निःसंतान को गुणवान संतान प्रदान करती हैं और निर्धन को पवित्र धन-ऐश्वर्य का स्वामी बना देती हैं।"),
            ("सकल मनोरथ सिद्ध करंता । जय जय जय महाकाली अनन्ता ॥ ३३ ॥", "आप भक्तों के समस्त धर्मानुकूल मनोरथों को सिद्ध करने वाली हैं; हे अनन्त महाकाली! आपकी सदा जय हो।"),
            ("काली चालीसा जो नित गावे । सो निश्चय भव पार परावे ॥ ३४ ॥", "जो मनुष्य इस महाकाली चालीसा का नित्य श्रद्धापूर्वक पाठ करता है, वह संसार के समस्त संकटों से पार उतर जाता है।"),
            ("प्रेम सहित जो पूजन कीन्हा । ताको प्रभु पद सहजहिं दीन्हा ॥ ३५ ॥", "जिसने भी निष्काम प्रेम से आपका पूजन और ध्यान किया, उसे आपने सहज ही अपना परम धाम प्रदान कर दिया।"),
            ("चारों फल जो पावन चाहै । काली चालीसा नित ध्यावै ॥ ३६ ॥", "जो धर्म, अर्थ, काम और मोक्ष—चारों फलों की प्राप्ति चाहता है, वह नित्य काली चालीसा का ध्यान करे।"),
            ("दीन दयाल दया निधि माता । मोहिं दीजै निज पावन त्राता ॥ ३७ ॥", "हे दीनदयालु माता! हे दया की सागर! मुझे अपने चरणों की नित्य सेवा का वरदान दीजिए।"),
            ("सदा रहो प्रभु अंग हमारे । जन्म मरण के बन्धन तारे ॥ ३८ ॥", "हे माँ! सदा मेरे अंग-संग रहिए और मुझे जन्म-मरण के सांसारिक फेर से पार उतार दीजिए।"),
